1	// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).
2	
3	export class PatchError extends Error {
4	  constructor(message, index) {
5	    super(message);
6	    this.name = 'PatchError';
7	    this.index = index;
8	  }
9	}
10	
11	const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
12	const INDEX_RE = /^(?:0|[1-9][0-9]*)$/;
13	const BAD_TILDE_RE = /~(?![01])/;
14	
15	export function parsePointer(pointer) {
16	  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
17	  if (pointer === '') return [];
18	  if (pointer[0] !== '/' || BAD_TILDE_RE.test(pointer)) throw new SyntaxError('invalid pointer');
19	  return pointer
20	    .slice(1)
21	    .split('/')
22	    .map((token) => token.replace(/~[01]/g, (m) => (m === '~0' ? '~' : '/')));
23	}
24	
25	// Internal failure while applying one operation; turned into a PatchError by applyPatch.
26	class OpFailure {
27	  constructor(reason) {
28	    this.reason = reason;
29	  }
30	}
31	
32	const isContainer = (v) => v !== null && typeof v === 'object';
33	
34	// Creates or overwrites an own data member without triggering setters such as __proto__.
35	function setMember(obj, name, value) {
36	  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
37	}
38	
39	function emptyLike(v) {
40	  return Array.isArray(v) ? [] : {};
41	}
42	
43	// Deep copy of a JSON value; iterative so deep values cannot overflow the stack.
44	function deepCopy(value) {
45	  if (!isContainer(value)) return value;
46	  const root = emptyLike(value);
47	  const stack = [[value, root]];
48	  while (stack.length > 0) {
49	    const [src, dst] = stack.pop();
50	    const keys = Array.isArray(src) ? null : Object.keys(src);
51	    const count = keys ? keys.length : src.length;
52	    for (let i = 0; i < count; i++) {
53	      const key = keys ? keys[i] : i;
54	      let child = src[key];
55	      if (isContainer(child)) {
56	        const copy = emptyLike(child);
57	        stack.push([child, copy]);
58	        child = copy;
59	      }
60	      if (keys) setMember(dst, key, child);
61	      else dst.push(child);
62	    }
63	  }
64	  return root;
65	}
66	
67	function deepEqual(a, b) {
68	  const stack = [[a, b]];
69	  while (stack.length > 0) {
70	    const [x, y] = stack.pop();
71	    if (!isContainer(x) || !isContainer(y)) {
72	      if (x !== y) return false;
73	      continue;
74	    }
75	    if (Array.isArray(x) !== Array.isArray(y)) return false;
76	    if (Array.isArray(x)) {
77	      if (x.length !== y.length) return false;
78	      for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
79	    } else {
80	      const keys = Object.keys(x);
81	      if (keys.length !== Object.keys(y).length) return false;
82	      for (const key of keys) {
83	        if (!Object.hasOwn(y, key)) return false;
84	        stack.push([x[key], y[key]]);
85	      }
86	    }
87	  }
88	  return true;
89	}
90	
91	// Returns the key that `token` names on `container`, or throws an OpFailure.
92	function childKey(container, token, notFound) {
93	  if (Array.isArray(container)) {
94	    if (INDEX_RE.test(token)) {
95	      if (Number(token) < container.length) return Number(token);
96	      throw new OpFailure(notFound);
97	    }
98	    if (token === '-') throw new OpFailure(notFound);
99	    throw new OpFailure('bad index');
100	  }
101	  if (isContainer(container) && Object.hasOwn(container, token)) return token;
102	  throw new OpFailure(notFound);
103	}
104	
105	function follow(doc, tokens, notFound) {
106	  let current = doc;
107	  for (const token of tokens) current = current[childKey(current, token, notFound)];
108	  return current;
109	}
110	
111	// Follows all tokens; returns the parent container and the key of the named value.
112	function locate(doc, tokens, notFound) {
113	  const parent = follow(doc, tokens.slice(0, -1), notFound);
114	  return { parent, key: childKey(parent, tokens[tokens.length - 1], notFound) };
115	}
116	
117	function add(doc, tokens, value) {
118	  if (tokens.length === 0) return value;
119	  const parent = follow(doc, tokens.slice(0, -1), 'path not found');
120	  const token = tokens[tokens.length - 1];
121	  if (Array.isArray(parent)) {
122	    if (token === '-') {
123	      parent.push(value);
124	    } else if (INDEX_RE.test(token)) {
125	      const index = Number(token);
126	      if (index > parent.length) throw new OpFailure('path not found');
127	      parent.splice(index, 0, value);
128	    } else {
129	      throw new OpFailure('bad index');
130	    }
131	  } else if (isContainer(parent)) {
132	    setMember(parent, token, value);
133	  } else {
134	    throw new OpFailure('path not found');
135	  }
136	  return doc;
137	}
138	
139	function remove(doc, tokens, notFound) {
140	  const { parent, key } = locate(doc, tokens, notFound);
141	  const value = parent[key];
142	  if (Array.isArray(parent)) parent.splice(key, 1);
143	  else delete parent[key];
144	  return value;
145	}
146	
147	function sameTokens(a, b) {
148	  return a.length === b.length && a.every((token, i) => token === b[i]);
149	}
150	
151	function isProperPrefix(prefix, tokens) {
152	  return prefix.length < tokens.length && prefix.every((token, i) => token === tokens[i]);
153	}
154	
155	function tryParsePointer(pointer) {
156	  if (typeof pointer !== 'string') return null;
157	  try {
158	    return parsePointer(pointer);
159	  } catch {
160	    return null;
161	  }
162	}
163	
164	// Checks one operation against the form rules; returns its parsed form or the failure reason.
165	function checkOperation(op) {
166	  if (op === null || typeof op !== 'object' || Array.isArray(op)) return { reason: 'not an object' };
167	  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
168	  if (typeof name !== 'string' || !OPS.has(name)) return { reason: 'bad op' };
169	  const path = Object.hasOwn(op, 'path') ? tryParsePointer(op.path) : null;
170	  if (path === null) return { reason: 'bad path' };
171	  let from = null;
172	  if (name === 'move' || name === 'copy') {
173	    from = Object.hasOwn(op, 'from') ? tryParsePointer(op.from) : null;
174	    if (from === null) return { reason: 'bad from' };
175	  }
176	  const hasValue = name === 'add' || name === 'replace' || name === 'test';
177	  if (hasValue && !Object.hasOwn(op, 'value')) return { reason: 'missing value' };
178	  if (name === 'remove' && path.length === 0) return { reason: 'cannot remove root' };
179	  if (name === 'move' && isProperPrefix(from, path)) return { reason: 'cannot move into own child' };
180	  return { op: { name, path, from, value: hasValue ? op.value : undefined } };
181	}
182	
183	function applyOperation(doc, { name, path, from, value }) {
184	  switch (name) {
185	    case 'add':
186	      return add(doc, path, deepCopy(value));
187	    case 'remove':
188	      remove(doc, path, 'path not found');
189	      return doc;
190	    case 'replace': {
191	      if (path.length === 0) return deepCopy(value);
192	      const { parent, key } = locate(doc, path, 'path not found');
193	      if (Array.isArray(parent)) parent[key] = deepCopy(value);
194	      else setMember(parent, key, deepCopy(value));
195	      return doc;
196	    }
197	    case 'move': {
198	      if (sameTokens(from, path)) {
199	        follow(doc, from, 'from not found');
200	        return doc;
201	      }
202	      const moved = remove(doc, from, 'from not found');
203	      return add(doc, path, moved);
204	    }
205	    case 'copy':
206	      return add(doc, path, deepCopy(follow(doc, from, 'from not found')));
207	    case 'test':
208	      if (!deepEqual(follow(doc, path, 'path not found'), value)) throw new OpFailure('test failed');
209	      return doc;
210	  }
211	}
212	
213	export function applyPatch(doc, patch) {
214	  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
215	  const ops = [];
216	  for (let i = 0; i < patch.length; i++) {
217	    const checked = checkOperation(patch[i]);
218	    if (checked.reason) throw new PatchError(`operation ${i}: ${checked.reason}`, i);
219	    ops.push(checked.op);
220	  }
221	  let result = deepCopy(doc);
222	  for (let i = 0; i < ops.length; i++) {
223	    try {
224	      result = applyOperation(result, ops[i]);
225	    } catch (err) {
226	      if (err instanceof OpFailure) throw new PatchError(`operation ${i}: ${err.reason}`, i);
227	      throw err;
228	    }
229	  }
230	  return result;
231	}
